steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(name: \"Support\") {
        nodes { id name key }
      }
      users(includeDisabled: true) {
        nodes { id name email }
      }
      issueLabels {
        nodes { id name teamId }
      }
    }"
  }'
